INSERT INTO `reflection_prompts` VALUES (1,1,'Which of these did you lean on most, and where?','Point to a real lesson or task. \"Throughout the unit\" is hard for your teacher to picture.',40,1),(2,2,'When did it get difficult, and what did you do about it?','The bit you found hard is usually the bit worth writing about.',50,1),(3,3,'What would you do differently next time?','One thing you will actually change, not \"work harder\".',30,1);
